func TestDomainTypes_TableDriven(t *testing.T) {
	// 1. CNPJ
	cnpjTests := []struct {
		val   string
		valid bool
	}{
		{"12345678000195", true},
		{"00000000000000", false}, // todos iguais
		{"11111111111111", false},
		{"12345678000190", false}, // DV inválido
		{"1234567800019", false},  // tamanho incorreto
		{"123456780001955", false},
	}
	for _, tc := range cnpjTests {
		err := CNPJ(tc.val).Validate()
		if tc.valid && err != nil {
			t.Errorf("CNPJ %s deveria ser válido, erro: %v", tc.val, err)
		}
		if !tc.valid && err == nil {
			t.Errorf("CNPJ %s deveria ser inválido, mas passou", tc.val)
		}
	}

	// 2. CPF
	cpfTests := []struct {
		val   string
		valid bool
	}{
		{"11144477735", true},
		{"11111111111", false}, // repetidos
		{"12345678900", false}, // DV inválido
		{"123456789", false},   // tamanho inválido
	}
	for _, tc := range cpfTests {
		err := CPF(tc.val).Validate()
		if tc.valid && err != nil {
			t.Errorf("CPF %s deveria ser válido, erro: %v", tc.val, err)
		}
		if !tc.valid && err == nil {
			t.Errorf("CPF %s deveria ser inválido, mas passou", tc.val)
		}
	}

	// 3. Chave de Acesso
	chaveTests := []struct {
		val   string
		valid bool
	}{
		{"35260112345678000195550010000000011000000012", true},
		{"35260112345678000195550010000000011000000011", false}, // DV errado
		{"3526011234567800019555001000000001100000001", false},  // tamanho menor
	}
	for _, tc := range chaveTests {
		err := ChaveAcesso(tc.val).Validate()
		if tc.valid && err != nil {
			t.Errorf("Chave %s deveria ser válida, erro: %v", tc.val, err)
		}
		if !tc.valid && err == nil {
			t.Errorf("Chave %s deveria ser inválida, mas passou", tc.val)
		}
	}

	// 4. Decimal de Precisão Arbitrária
	decTests := []struct {
		val       string
		decimals  int
		expectErr bool
	}{
		{"100.50", 2, false},
		{"100.505", 2, true}, // excesso de casas
		{"100.5000", 4, false},
		{"abc", 2, true}, // não numérico
		{"100.20.30", 2, true},
	}
	for _, tc := range decTests {
		err := NewDecimal(tc.val).Validate(tc.decimals)
		if tc.expectErr && err == nil {
			t.Errorf("Decimal %s com %d casas deveria falhar", tc.val, tc.decimals)
		}
		if !tc.expectErr && err != nil {
			t.Errorf("Decimal %s com %d casas não deveria falhar: %v", tc.val, tc.decimals, err)
		}
	}
}

func TestNFe_ValidationFlow(t *testing.T) {
	doc := createValidMockNFe()

	// Validação de documento válido
	if err := doc.Validate(); err != nil {
		t.Fatalf("documento mock válido falhou na validação: %v", err)
	}

	// Testa falha estrutural por ausência de CNPJ e CPF no emitente (Choice)
	docInvalid := createValidMockNFe()
	docInvalid.InfNFe.Emit.CNPJ = ""
	docInvalid.InfNFe.Emit.CPF = ""
	errChoice := docInvalid.Validate()
	if errChoice == nil {
		t.Fatalf("esperado erro de validação por emitente sem CNPJ e CPF")
	}
	if !strings.Contains(errChoice.Error(), "CHOICE_REQUIRED") {
		t.Errorf("esperado código CHOICE_REQUIRED, obteve: %v", errChoice)
	}
}

func TestNFe_Regra_LA01_30_Rejeicao1106(t *testing.T) {
	doc := createValidMockNFe()
	// Configura cClassTrib de combustível (410013) sem preencher det.Prod.Comb
	doc.InfNFe.Det[0].Imposto.IBSCBS.CClassTrib = "410013"
	doc.InfNFe.Det[0].Prod.Comb = nil

	err := doc.Validate()
	if err == nil {
		t.Fatalf("esperada Rejeição 1106 para cClassTrib de combustível sem prod.comb")
	}
	if !strings.Contains(err.Error(), "1106") {
		t.Errorf("erro deve conter código de rejeição 1106: %v", err)
	}

	// Agora adiciona grupo Comb e deve passar
	doc.InfNFe.Det[0].Prod.Comb = &Comb{
		CProdANP: "320101001",
		DescANP:  "GASOLINA COMUM",
		UFCons:   "SP",
	}
	if err := doc.Validate(); err != nil {
		t.Errorf("não deveria rejeitar após preencher comb: %v", err)
	}
}

func TestNFe_Regra_I05k10_Rejeicao1165(t *testing.T) {
	// Caso 1: NF-e modelo 55 com crédito presumido IBS ZFM é PERMITIDO
	doc55 := createValidMockNFe()
	doc55.InfNFe.Ide.Mod = ModeloNFe
	doc55.InfNFe.Det[0].Prod.TpCredPresIBSZFM = "1"
	doc55.InfNFe.Det[0].Imposto.IBSCBS.GCredPresIBSZFM = &GCredPresIBSZFM{
		TpCredPresIBSZFM: "1",
		VCredPresIBSZFM:  NewDecimal("10.00"),
	}
	if err := doc55.Validate(); err != nil {
		t.Errorf("modelo 55 não deve ser rejeitado pela regra I05k-10: %v", err)
	}

	// Caso 2: NFC-e modelo 65 COM tpCredPresIBSZFM -> Violação da Regra I05k-10 (Rejeição 1165)
	doc65 := createValidMockNFe()
	doc65.InfNFe.Ide.Mod = ModeloDocumentoNFCe
	doc65.InfNFe.Det[0].Prod.TpCredPresIBSZFM = "1"
	doc65.InfNFe.Det[0].Imposto.IBSCBS.GCredPresIBSZFM = &GCredPresIBSZFM{
		TpCredPresIBSZFM: "1",
		VCredPresIBSZFM:  NewDecimal("10.00"),
	}
	// IBS/CBS por si só não aciona I05k-10.
	docAllowed := createValidMockNFe()
	docAllowed.InfNFe.Ide.Mod = ModeloDocumentoNFCe
	if err := docAllowed.Validate(); err != nil {
		t.Fatalf("IBS/CBS sem classificação ZFM não deve ser bloqueado: %v", err)
	}
	err := doc65.Validate()
	if err == nil {
		t.Fatalf("NFC-e modelo 65 com tpCredPresIBSZFM deveria ter sido rejeitada pela regra I05k-10")
	}

	valErrs, ok := err.(ValidationErrors)
	if !ok {
		t.Fatalf("esperado ValidationErrors, obteve %T", err)
	}

	foundRule := false
	for _, e := range valErrs {
		if e.Code == "1165" && e.RuleID == "I05k-10" {
			foundRule = true
			if e.Severity != SeverityError {
				t.Errorf("severidade da rejeição deve ser error, obteve %s", e.Severity)
			}
			break
		}
	}
	if !foundRule {
		t.Errorf("rejeição oficial 1165 da regra I05k-10 não encontrada nos erros: %v", valErrs)
	}
}

func TestNFe_DocumentedRulesCatalog(t *testing.T) {
	rules := GetDocumentedRules()
	if len(rules) == 0 {
		t.Fatalf("catálogo de regras documentadas não deve estar vazio")
	}
	foundLA01 := false
	for _, r := range rules {
		if r.Code == "LA01-30" && r.Status == RuleStatusAutomated {
			foundLA01 = true
			break
		}
	}
	if !foundLA01 {
		t.Errorf("regra LA01-30 com status automated não encontrada no catálogo")
	}
}

func TestNFe_SpecificationMetadata(t *testing.T) {
	meta := GetSpecificationMetadata()
	if meta.Family == "" || meta.LayoutVersion == "" || meta.GeneratorVersion == "" {
		t.Errorf("metadados da especificação incompletos: %+v", meta)
	}

	specs := SupportedSpecifications()
	if len(specs) == 0 {
		t.Errorf("lista de especificações suportadas não deve estar vazia")
	}
}

func TestNFe_XMLRoundTrip(t *testing.T) {
	docOriginal := createValidMockNFe()
	xmlBytes, err := docOriginal.ToXMLCompact()
	if err != nil {
		t.Fatalf("falha ao serializar XML: %v", err)
	}
	if !strings.Contains(string(xmlBytes), "infNFe") {
		t.Fatalf("XML serializado não contém infNFe")
	}

	docParsed, err := UnmarshalXML(xmlBytes)
	if err != nil {
		t.Fatalf("falha ao desserializar XML: %v", err)
	}

	if docParsed.InfNFe.Id != docOriginal.InfNFe.Id {
		t.Errorf("roundtrip falhou para Id: esperado %s, obteve %s", docOriginal.InfNFe.Id, docParsed.InfNFe.Id)
	}
	if docParsed.InfNFe.Emit.CNPJ != docOriginal.InfNFe.Emit.CNPJ {
		t.Errorf("roundtrip falhou para CNPJ emitente: esperado %s, obteve %s", docOriginal.InfNFe.Emit.CNPJ, docParsed.InfNFe.Emit.CNPJ)
	}
}

func TestNFe_JSONRoundTrip(t *testing.T) {
	docOriginal := createValidMockNFe()
	jsonBytes, err := docOriginal.ToJSON()
	if err != nil {
		t.Fatalf("falha ao serializar JSON: %v", err)
	}

	docParsed, err := UnmarshalJSON(jsonBytes)
	if err != nil {
		t.Fatalf("falha ao desserializar JSON: %v", err)
	}

	if docParsed.InfNFe.Ide.NatOp != docOriginal.InfNFe.Ide.NatOp {
		t.Errorf("JSON roundtrip falhou: esperado %s, obteve %s", docOriginal.InfNFe.Ide.NatOp, docParsed.InfNFe.Ide.NatOp)
	}
}

// TestXMLLint_ConformidadeXSD executa validação rigorosa de XMLs contra os XSDs oficiais via xmllint (libxml2).
func TestXMLLint_ConformidadeXSD(t *testing.T) {
	xmllintPath, err := exec.LookPath("xmllint")
	if err != nil {
		t.Fatalf("xmllint (libxml2) é obrigatório para conformidade de schemas XSD da SEFAZ, mas não foi encontrado no PATH. Instale com: sudo apt-get install -y libxml2-utils")
	}

	// Procura pasta schemas/
	schemasDir := "../schemas"
	if _, err := os.Stat(schemasDir); os.IsNotExist(err) {
		schemasDir = "schemas"
	}
	if _, err := os.Stat(schemasDir); os.IsNotExist(err) {
		t.Fatal("pasta schemas/ não localizada para validação xmllint")
	}

	xsdFile := filepath.Join(schemasDir, "nfe/captured-b329ecbe7e4c/PL_010g_v1.03/NFe/nfe_v4.00.xsd")
	if _, err := os.Stat(xsdFile); os.IsNotExist(err) {
		t.Fatalf("XSD oficial da NFe não encontrado em %s", xsdFile)
	}

	doc := createValidMockNFe()
	xmlBytes, err := doc.ToXMLIndent("", "  ")
	if err != nil {
		t.Fatalf("falha ao serializar NFe: %v", err)
	}

	tmpXML, err := os.CreateTemp("", "nfe-*.xml")
	if err != nil {
		t.Fatalf("falha ao criar arquivo temporário: %v", err)
	}
	defer os.Remove(tmpXML.Name())

	if _, err := tmpXML.Write(xmlBytes); err != nil {
		t.Fatalf("falha ao escrever XML: %v", err)
	}
	tmpXML.Close()

	cmd := exec.Command(xmllintPath, "--noout", "--schema", xsdFile, tmpXML.Name())
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("Erro de validação xmllint contra XSD oficial:\n%s\nXML gerado:\n%s", string(out), string(xmlBytes))
	}
}

// TestGoldenFixtures_XMLLint valida as fixtures golden oficiais contra o XSD oficial da SEFAZ.
func TestGoldenFixtures_XMLLint(t *testing.T) {
	xmllintPath, err := exec.LookPath("xmllint")
	if err != nil {
		t.Fatal("xmllint não encontrado no PATH")
	}

	schemasDir := "../schemas"
	if _, err := os.Stat(schemasDir); os.IsNotExist(err) {
		schemasDir = "schemas"
	}
	if _, err := os.Stat(schemasDir); os.IsNotExist(err) {
		t.Fatal("pasta schemas/ não localizada para validação xmllint")
	}
	xsdFile := filepath.Join(schemasDir, "nfe/captured-b329ecbe7e4c/PL_010g_v1.03/NFe/nfe_v4.00.xsd")
	if _, err := os.Stat(xsdFile); os.IsNotExist(err) {
		t.Fatalf("XSD oficial da NFe não encontrado em %s", xsdFile)
	}

	goldenFiles := []string{
		"../testdata/golden/minimal.xml",
		"../testdata/golden/reforma_tributaria.xml",
	}

	for _, gFile := range goldenFiles {
		if _, err := os.Stat(gFile); os.IsNotExist(err) {
			continue
		}
		cmd := exec.Command(xmllintPath, "--noout", "--schema", xsdFile, gFile)
		out, err := cmd.CombinedOutput()
		if err != nil {
			t.Fatalf("Golden fixture %s falhou na validação xmllint:\n%s", gFile, string(out))
		}
	}
}

// TestNegativeFixtures_XMLLint comprova que fixtures deliberadamente incorretas são rejeitadas pelo validador XSD.
func TestNegativeFixtures_XMLLint(t *testing.T) {
	xmllintPath, err := exec.LookPath("xmllint")
	if err != nil {
		t.Fatal("xmllint não encontrado no PATH")
	}

	schemasDir := "../schemas"
	if _, err := os.Stat(schemasDir); os.IsNotExist(err) {
		schemasDir = "schemas"
	}
	if _, err := os.Stat(schemasDir); os.IsNotExist(err) {
		t.Fatal("pasta schemas/ não localizada para validação xmllint")
	}
	xsdFile := filepath.Join(schemasDir, "nfe/captured-b329ecbe7e4c/PL_010g_v1.03/NFe/nfe_v4.00.xsd")
	if _, err := os.Stat(xsdFile); os.IsNotExist(err) {
		t.Fatalf("XSD oficial da NFe não encontrado em %s", xsdFile)
	}

	negativeFiles := []string{
		"../testdata/negative/missing_required.xml",
		"../testdata/negative/invalid_enum.xml",
		"../testdata/negative/invalid_choice_both.xml",
	}

	for _, nFile := range negativeFiles {
		if _, err := os.Stat(nFile); os.IsNotExist(err) {
			continue
		}
		cmd := exec.Command(xmllintPath, "--noout", "--schema", xsdFile, nFile)
		_, err := cmd.CombinedOutput()
		if err == nil {
			t.Fatalf("Fixture deliberadamente negativa %s deveria ter sido rejeitada pelo XSD, mas passou!", nFile)
		}
	}
}

